// Android TV support for the phone APK: a leanback launcher entry, the TV banner, a touchscreen that
// is optional, and a landscape TV beside a portrait phone. `android/` is generated by prebuild and
// not in git, so every change lives here rather than in the native project.
const { withAndroidManifest, withMainActivity, withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const LEANBACK_FEATURE = 'android.software.leanback';
const TOUCHSCREEN_FEATURE = 'android.hardware.touchscreen';
const LEANBACK_CATEGORY = 'android.intent.category.LEANBACK_LAUNCHER';
const LAUNCHER_CATEGORY = 'android.intent.category.LAUNCHER';
const MAIN_ACTION = 'android.intent.action.MAIN';
const BANNER_ATTRIBUTE = 'android:banner';
const BANNER_DRAWABLE = '@drawable/tv_banner';
const BANNER_SOURCE = path.join('assets', 'icon', 'tv-banner.png');
const BANNER_TARGET = path.join('android', 'app', 'src', 'main', 'res', 'drawable-xhdpi', 'tv_banner.png');
// Marker comment so a second prebuild does not insert the portrait lock a second time.
const PORTRAIT_MARKER = 'earmark-tv-portrait-lock';
const PORTRAIT_LOCK =
  `    // ${PORTRAIT_MARKER}: a phone stays portrait, a TV (leanback) is left to the system.\n` +
  '    if (!packageManager.hasSystemFeature("android.software.leanback")) requestedOrientation = android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT\n';

const attr = (name) => ({ $: { 'android:name': name } });
const hasName = (list, name) => (list ?? []).some((c) => c.$?.['android:name'] === name);

/** The activity that answers the normal launcher: the one place the leanback category and the orientation go. */
function findLauncherActivity(manifest) {
  const activities = manifest?.manifest?.application?.[0]?.activity ?? [];
  return activities.find((a) => (a['intent-filter'] ?? []).some((f) =>
    hasName(f.action, MAIN_ACTION) && hasName(f.category, LAUNCHER_CATEGORY)));
}

/**
 * The whole manifest transformation, kept pure (takes and returns the parsed manifest) so it can be
 * unit-tested without a prebuild. Every step is idempotent.
 */
function applyAndroidTVManifest(manifest) {
  const root = manifest.manifest;
  // 1. Leanback and touchscreen are both optional: the same APK runs on a TV and on a phone.
  root['uses-feature'] = root['uses-feature'] ?? [];
  for (const name of [LEANBACK_FEATURE, TOUCHSCREEN_FEATURE]) {
    if (!hasName(root['uses-feature'], name)) root['uses-feature'].push({ $: { 'android:name': name, 'android:required': 'false' } });
  }

  // 3. The banner the TV launcher shows on the home screen.
  const application = root.application?.[0];
  if (application) {
    application.$ = application.$ ?? {};
    application.$[BANNER_ATTRIBUTE] = BANNER_DRAWABLE;
  }

  const activity = findLauncherActivity(manifest);
  if (activity) {
    // 2. Keep LAUNCHER and add the leanback launcher next to it, on the same filter.
    for (const filter of activity['intent-filter'] ?? []) {
      if (!hasName(filter.category, LAUNCHER_CATEGORY)) continue;
      filter.category = filter.category ?? [];
      if (!hasName(filter.category, LEANBACK_CATEGORY)) filter.category.push(attr(LEANBACK_CATEGORY));
    }
    // 5. A TV is landscape: drop Expo's portrait lock and let MainActivity lock only non-TV devices.
    if (activity.$) delete activity.$['android:screenOrientation'];
  }
  return manifest;
}

/** Android TV: leanback feature, launcher category, banner, landscape, and the portrait lock for phones. */
function withAndroidTV(config) {
  config = withAndroidManifest(config, (c) => {
    c.modResults = applyAndroidTVManifest(c.modResults);
    return c;
  });

  config = withMainActivity(config, (c) => {
    if (c.modResults.contents.includes(PORTRAIT_MARKER)) return c;
    const lines = c.modResults.contents.split('\n');
    const at = lines.findIndex((l) => l.includes('super.onCreate'));
    if (at < 0) throw new Error(`withAndroidTV: no super.onCreate in ${c.modResults.path} to insert the portrait lock before`);
    lines.splice(at, 0, PORTRAIT_LOCK.trimEnd());
    c.modResults.contents = lines.join('\n');
    return c;
  });

  return withDangerousMod(config, ['android', async (c) => {
    const from = path.join(c.modRequest.projectRoot, BANNER_SOURCE);
    const to = path.join(c.modRequest.projectRoot, BANNER_TARGET);
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(from, to);
    return c;
  }]);
}

module.exports = withAndroidTV;
module.exports.applyAndroidTVManifest = applyAndroidTVManifest;
module.exports.findLauncherActivity = findLauncherActivity;
